 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colored_rows = [r for r in range(h) if any(grid[r][c] != 0 for c in range(w))]
    if not colored_rows:
        return [row[:] for row in grid]
    bottom = max(colored_rows)
    out = [[0] * w for _ in range(h)]
    for r in range(h):
        shift = bottom - r
        for c in range(w):
            if grid[r][c] != 0:
                nc = c - shift
                if 0 <= nc < w:
                    out[r][nc] = grid[r][c]
    return out
